// Transient bootstrap discovery test; names are generated by the harness.
// It never contacts the real daemon, user configuration or credentials.
#include <mach/mach.h>
#include <mach/port.h>
#include <servers/bootstrap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct { mach_msg_header_t h; unsigned marker; } msg_t;
int main(int argc,char **argv) {
    setvbuf(stdout,NULL,_IONBF,0);
    if(argc<3) return 1;
    char *name=argv[2];
    if(!strcmp(argv[1],"lookup")) {
        mach_port_t service=MACH_PORT_NULL; kern_return_t kr=bootstrap_look_up(bootstrap_port,name,&service);
        printf("lookup_kr=%d valid=%d\n",kr,MACH_PORT_VALID(service));
        if(kr || !MACH_PORT_VALID(service)) return 4;
        if(argc==5 && !strcmp(argv[3],"hold")) {
            FILE *ready=fopen(argv[4],"w");if(!ready){perror("holder ready");return 2;}fputs("ready\n",ready);fclose(ready);
            char release;if(read(STDIN_FILENO,&release,1)!=1)return 6;
            msg_t old={0};old.h.msgh_bits=MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND,0);old.h.msgh_remote_port=service;old.h.msgh_size=sizeof(old);old.h.msgh_id=4812;old.marker=0xa511;
            kern_return_t old_kr=mach_msg(&old.h,MACH_SEND_MSG|MACH_SEND_TIMEOUT,sizeof(old),0,0,1000,0);
            mach_port_t replacement=MACH_PORT_NULL; kern_return_t lookup_kr=bootstrap_look_up(bootstrap_port,name,&replacement),new_kr=KERN_FAILURE;
            if(!lookup_kr && MACH_PORT_VALID(replacement)) {
                msg_t fresh={0};fresh.h.msgh_bits=MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND,0);fresh.h.msgh_remote_port=replacement;fresh.h.msgh_size=sizeof(fresh);fresh.h.msgh_id=4811;fresh.marker=0xa522;
                new_kr=mach_msg(&fresh.h,MACH_SEND_MSG|MACH_SEND_TIMEOUT,sizeof(fresh),0,0,1000,0);
                (void)mach_port_deallocate(mach_task_self(),replacement);
            }
            printf("old_send_kr=%d new_lookup_kr=%d new_send_kr=%d\n",old_kr,lookup_kr,new_kr);
            (void)mach_port_deallocate(mach_task_self(),service);
            return old_kr!=KERN_SUCCESS && lookup_kr==KERN_SUCCESS && new_kr==KERN_SUCCESS ? 0 : 7;
        }
        if(argc==4 && !strcmp(argv[3],"send")) {
            msg_t msg={0};msg.h.msgh_bits=MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND,0);msg.h.msgh_remote_port=service;msg.h.msgh_size=sizeof(msg);msg.h.msgh_id=4811;msg.marker=0xa522;
            kr=mach_msg(&msg.h,MACH_SEND_MSG|MACH_SEND_TIMEOUT,sizeof(msg),0,0,1000,0);
            printf("send_kr=%d\n",kr);(void)mach_port_deallocate(mach_task_self(),service);return kr?5:0;
        }
        (void)mach_port_deallocate(mach_task_self(),service);return 0;
    }
    if(strcmp(argv[1],"server") || argc!=4) return 1;
    mach_port_t receive=MACH_PORT_NULL;
    kern_return_t kr=mach_port_allocate(mach_task_self(),MACH_PORT_RIGHT_RECEIVE,&receive);
    if(kr) {printf("allocate_kr=%d\n",kr);return 2;}
    kr=mach_port_guard_with_flags(mach_task_self(),receive,0xa522,MPG_IMMOVABLE_RECEIVE);
    if(kr) {printf("guard_kr=%d\n",kr);return 2;}
    kr=mach_port_insert_right(mach_task_self(),receive,receive,MACH_MSG_TYPE_MAKE_SEND);
    if(kr) {printf("insert_kr=%d\n",kr);return 2;}
    kr=bootstrap_register(bootstrap_port,name,receive);
    printf("register_kr=%d pid=%d\n",kr,getpid());
    FILE *ready=fopen(argv[3],"w");if(!ready){perror("ready");return 2;}fprintf(ready,"%d\n",kr);fclose(ready);
    if(kr) return 3;
    struct {msg_t msg;unsigned char trailer[128];} received={0};
    kr=mach_msg(&received.msg.h,MACH_RCV_MSG|MACH_RCV_TIMEOUT,0,sizeof(received),receive,6000,0);
    printf("receive_kr=%d marker=%u\n",kr,received.msg.marker);
    if(kr || received.msg.marker!=0xa522) return 4;
    char release; if(read(STDIN_FILENO,&release,1)!=1)return 5;
    return 0; // process exit releases the guarded receive right
}
